 $('celebrationTitle').textContent=c.name.toUpperCase();$('celebrationPlayer').textContent=(celebration.preview?'PRACTICE · ':a.team===0?'TOUCHDOWN! · ':'CPU TOUCHDOWN · ')+a.name+' #'+a.jerseyNumber;
