function getKickDraft(){const p=game.placeKick;if(!p){kickDraft=null;return;}if(!kickDraft||kickDraft.id!==p.id||game.offense!==0)kickDraft={id:p.id,aim:p.aim,power:p.power};return kickDraft;}
